
@php($questions=json_decode(old('questions',''),true)?:($record?->questions??[]))
<section x-data="questionEditor({{ \Illuminate\Support\Js::from($questions) }})" class="editor"><input type="hidden" name="questions" :value="JSON.stringify(questions)"><h2>Editor de preguntas</h2><p class="muted">Los puntajes de pruebas son orientativos; el sistema no decide la integración.</p><template x-for="(q,i) in questions" :key="i"><article class="builder-item"><div class="sectionhead"><strong x-text="'Pregunta '+(i+1)"></strong><button type="button" class="quiet small" @click="questions.splice(i,1)">Eliminar</button></div><div class="row"><div><label>Identificador</label><input x-model="q.id"></div><div><label>Tipo</label><select x-model="q.type"><option value="text">Texto corto</option><option value="paragraph">Texto largo</option><option value="select">Una opción</option><option value="multiselect">Varias opciones</option><option value="number">Número</option><option value="date">Fecha</option><option value="checkbox">Confirmación</option></select></div></div><label>Pregunta</label><input x-model="q.label"><label class="inline"><input type="checkbox" x-model="q.required">Obligatoria</label><label class="inline"><input type="checkbox" x-model="q.sensitive">Dato sensible</label><div x-show="['select','multiselect'].includes(q.type)"><label>Opciones (una por línea)</label><textarea :value="q.options.join('\n')" @input="q.options=$el.value.split('\n').filter(x=>x.trim())"></textarea>
@if($catalog==='tests')
<template x-for="option in q.options"><div class="row"><label x-text="option"></label><input type="number" :value="q.scores[option]||0" @input="q.scores[option]=Number($el.value)" aria-label="Puntaje"></div></template>
@endif
</div><details><summary>Vista previa de la pregunta</summary><label x-text="q.label"></label><input disabled x-show="!['paragraph','select','multiselect','checkbox'].includes(q.type)"><textarea disabled x-show="q.type==='paragraph'"></textarea><select disabled x-show="q.type==='select'"><option>Selecciona una opción</option><template x-for="option in q.options"><option x-text="option"></option></template></select><div x-show="q.type==='multiselect'"><template x-for="option in q.options"><label class="inline"><input type="checkbox" disabled><span x-text="option"></span></label></template></div><input type="checkbox" disabled x-show="q.type==='checkbox'"></details></article></template><button type="button" class="secondary" @click="addQuestion">Agregar pregunta</button><noscript>Activa JavaScript para editar preguntas.</noscript></section>
